  echo "!! REFUSING TO START: javac is not runnable in this container."
  echo "!! tried: javac -version"
  echo "!! openjdk-25-jdk-headless is installed by Airlock's own Containerfile"
  exit 4
fi
javac -version 2>&1 | head -2
